a_gout_coh_inc_01_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_01_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GOUT' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_01_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GOUT' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
-- GOUT-COH-INC-01 (inclusion): 曾經診斷痛風（ICD-10-CM M10 或 M1A）之病人。
c_gout_coh_inc_01 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gout_coh_inc_01_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gout_coh_inc_01_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gout_coh_inc_01_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gout_coh_inc_01_1.ev, a_gout_coh_inc_01_1_off.ev, a_gout_coh_inc_01_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gout_coh_inc_01_1 ON a_gout_coh_inc_01_1.pid = b.pid AND a_gout_coh_inc_01_1.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_01_1_nd ON a_gout_coh_inc_01_1_nd.pid = b.pid AND a_gout_coh_inc_01_1_nd.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_01_1_off ON a_gout_coh_inc_01_1_off.pid = b.pid AND a_gout_coh_inc_01_1_off.index_date = b.index_date),
a_gout_coh_inc_02_1 AS (
  SELECT d.pid, d.index_date, CASE WHEN (u.n IS NULL OR (d.v AND u.not_true = 0) OR (NOT d.v AND u.not_false = 0)) THEN d.v END AS v,
         CASE WHEN (u.n IS NULL OR (d.v AND u.not_true = 0) OR (NOT d.v AND u.not_false = 0)) OR d.v IS NULL THEN d.ev ELSE u.ev END AS ev
  FROM (SELECT pid, index_date, (CASE WHEN o.value_cmp IS NULL THEN (o.value_num >= 6) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num < 6 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num >= 6 THEN TRUE END) END) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || coalesce(strftime(o.effective, '%Y-%m-%d'), '') AS ev
    FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
