r(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) AS value_num, o.value_cmp, o.value_code,
         (o.value_num IS NOT NULL AND (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/dl' THEN o.value_num WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '2160-0' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'umol/l' THEN round(o.value_num / 88.4, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/100ml' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/dl' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/l' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) IS NULL) AS unit_bad, o.effective IS NULL AS undated
  FROM base b JOIN observation o ON o.pid = b.pid
   AND (o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date OR o.effective IS NULL)
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_SERUM_URATE' AND vs.system = o.system AND vs.code = o.code)) WHERE NOT undated) o WHERE rn = 1) d
  LEFT JOIN (SELECT pid, index_date, count(*) AS n,
         count(*) FILTER (WHERE (CASE WHEN o.value_cmp IS NULL THEN (o.value_num >= 6) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num < 6 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num >= 6 THEN TRUE END) END) IS NOT TRUE) AS not_true,
         count(*) FILTER (WHERE (CASE WHEN o.value_cmp IS NULL THEN (o.value_num >= 6) WHEN o.value_cmp IN ('<', '<=') THEN (CASE WHEN o.value_num < 6 THEN FALSE END) WHEN o.value_cmp IN ('>', '>=') THEN (CASE WHEN o.value_num >= 6 THEN TRUE END) END) IS NOT FALSE) AS not_false, string_agg(CASE WHEN o.undated THEN o.oid || '|' || coalesce(strftime(o.effective, '%Y-%m-%d'), '') END, ';' ORDER BY o.oid) AS ev
    FROM (SELECT b.pid, b.index_date, o.oid, o.effective, (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/dl' THEN o.value_num WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '2160-0' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'umol/l' THEN round(o.value_num / 88.4, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/100ml' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/dl' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/l' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) AS value_num, o.value_cmp, o.value_code,
         (o.value_num IS NOT NULL AND (CASE WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/dl' THEN o.value_num WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '1988-5' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) WHEN o.system = 'http://loinc.org' AND o.code = '2160-0' AND replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'umol/l' THEN round(o.value_num / 88.4, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/100ml' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/dl' THEN round(o.value_num * 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'g/l' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg%' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/100ml' THEN round(o.value_num * 1.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/l' THEN round(o.value_num / 10.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'mg/ml' THEN round(o.value_num * 100.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/dl' THEN round(o.value_num / 1000.0, 6) WHEN replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(coalesce(o.unit, '')), ' ', ''), 'µ', 'u'), 'μ', 'u'), '^', '*'), '{', ''), '}', ''), '[', ''), ']', ''), '_', '') = 'ug/ml' THEN round(o.value_num / 10.0, 6) END) IS NULL) AS unit_bad, o.effective IS NULL AS undated
  FROM base b JOIN observation o ON o.pid = b.pid
   AND (o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date OR o.effective IS NULL)
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_SERUM_URATE' AND vs.system = o.system AND vs.code = o.code)) o WHERE o.undated GROUP BY pid, index_date) u
    ON u.pid = d.pid AND u.index_date = d.index_date),
-- GOUT-COH-INC-02 (inclusion): 一年內最近一次血清尿酸值大於或等於 6.0 mg/dL。
c_gout_coh_inc_02 AS (
  SELECT b.pid, b.index_date, a_gout_coh_inc_02_1.v AS v,
         concat_ws(';', a_gout_coh_inc_02_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gout_coh_inc_02_1 ON a_gout_coh_inc_02_1.pid = b.pid AND a_gout_coh_inc_02_1.index_date = b.index_date),
a_gout_coh_inc_03_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -180) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_03_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc))) OR (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_03_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc)) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_URATE_LOWERING_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -180) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- GOUT-COH-INC-03 (inclusion): 六個月內曾使用降尿酸藥物。
c_gout_coh_inc_03 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gout_coh_inc_03_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gout_coh_inc_03_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gout_coh_inc_03_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gout_coh_inc_03_1.ev, a_gout_coh_inc_03_1_off.ev, a_gout_coh_inc_03_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gout_coh_inc_03_1 ON a_gout_coh_inc_03_1.pid = b.pid AND a_gout_coh_inc_03_1.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_03_1_nd ON a_gout_coh_inc_03_1_nd.pid = b.pid AND a_gout_coh_inc_03_1_nd.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_03_1_off ON a_gout_coh_inc_03_1_off.pid = b.pid AND a_gout_coh_inc_03_1_off.index_date = b.index_date),
a_gout_coh_inc_04_1 AS (
  SELECT b.pid, b.index_date, count(DISTINCT e.visit) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d, coalesce('Encounter/' || eid, 'Condition/' || cid) AS visit FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_04_1_nd AS (
  SELECT b.pid, b.index_date, count(DISTINCT e.visit) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d, coalesce('Encounter/' || eid, 'Condition/' || cid) AS visit FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GOUT' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_04_1_r AS (
  SELECT b.pid, b.index_date, count(DISTINCT e.visit) AS n
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d, coalesce('Encounter/' || eid, 'Condition/' || cid) AS visit, FALSE AS undated FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)
    UNION ALL SELECT pid, cid AS rid, coalesce(onset, recorded) AS d, coalesce('Encounter/' || eid, 'Condition/' || cid) AS visit, TRUE FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GOUT' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code)))) e
    ON e.pid = b.pid AND ((e.undated AND e.d IS NULL) OR (NOT e.undated AND e.d BETWEEN (b.index_date + -365) AND b.index_date))
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_04_1_off AS (
  SELECT b.pid, b.index_date, count(DISTINCT e.visit) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d, coalesce('Encounter/' || eid, 'Condition/' || cid) AS visit FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_GOUT' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_GOUT' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- GOUT-COH-INC-04 (inclusion): 一年內因痛風就診二次以上。
c_gout_coh_inc_04 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gout_coh_inc_04_1.n, 0) >= 2) THEN TRUE WHEN coalesce(a_gout_coh_inc_04_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gout_coh_inc_04_1_r.n, 0) >= 2) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gout_coh_inc_04_1.ev, a_gout_coh_inc_04_1_off.ev, a_gout_coh_inc_04_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gout_coh_inc_04_1 ON a_gout_coh_inc_04_1.pid = b.pid AND a_gout_coh_inc_04_1.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_04_1_nd ON a_gout_coh_inc_04_1_nd.pid = b.pid AND a_gout_coh_inc_04_1_nd.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_04_1_r ON a_gout_coh_inc_04_1_r.pid = b.pid AND a_gout_coh_inc_04_1_r.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_04_1_off ON a_gout_coh_inc_04_1_off.pid = b.pid AND a_gout_coh_inc_04_1_off.index_date = b.index_date),
a_gout_coh_inc_05_1_creatinine AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END)) AND (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END) > 0.0 THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
    WHERE o.system = 'http://loinc.org' AND o.code = '2160-0') WHERE rn = 1),
a_gout_coh_inc_05_1_v AS (
  SELECT b.pid, b.index_date, (CASE WHEN creatinine.conv IS NULL OR (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) IS NULL OR (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) < 18 OR (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) IS NULL THEN NULL ELSE 142.0 * pow(least(creatinine.conv / (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN 0.7 ELSE 0.9 END), 1.0), (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN -0.241 ELSE -0.302 END)) * pow(greatest(creatinine.conv / (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN 0.7 ELSE 0.9 END), 1.0), -1.2) * pow(0.9938, (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END)) * (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN 1.012 ELSE 1.0 END) END) AS val, concat_ws(';', creatinine.oid || '|' || strftime(creatinine.effective, '%Y-%m-%d')) AS refs,
         (CASE WHEN creatinine.oid IS NULL OR creatinine.value_num IS NULL THEN 'derived_missing_input:creatinine' WHEN creatinine.conv IS NULL THEN 'derived_unit:creatinine' WHEN (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) IS NULL OR (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) <= 0 THEN 'derived_missing_input:age' WHEN (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) < 18 THEN 'derived_adult_only:age' WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) IS NULL THEN 'derived_missing_input:sex' ELSE 'derived_missing_input' END) AS why
  FROM base b
  LEFT JOIN a_gout_coh_inc_05_1_creatinine creatinine ON creatinine.pid = b.pid AND creatinine.index_date = b.index_date),
a_gout_coh_inc_05_1 AS (
  SELECT pid, index_date, val, CASE WHEN val IS NULL THEN why ELSE refs END AS ev
  FROM a_gout_coh_inc_05_1_v),
-- GOUT-COH-INC-05 (inclusion): 一年內最近一次 eGFR 小於 60 mL/min/1.73m²（慢性腎臟病第三期以上）。
c_gout_coh_inc_05 AS (
  SELECT b.pid, b.index_date, (a_gout_coh_inc_05_1.val < 60) AS v,
         concat_ws(';', a_gout_coh_inc_05_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gout_coh_inc_05_1 ON a_gout_coh_inc_05_1.pid = b.pid AND a_gout_coh_inc_05_1.index_date = b.index_date),
a_gout_coh_inc_06_1_weight AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[lb_av]' THEN o.value_num * 0.45359237 WHEN 'g' THEN o.value_num * 0.001 WHEN 'kg' THEN o.value_num * 1.0 WHEN 'lb' THEN o.value_num * 0.45359237 ELSE NULL END)) THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[lb_av]' THEN o.value_num * 0.45359237 WHEN 'g' THEN o.value_num * 0.001 WHEN 'kg' THEN o.value_num * 1.0 WHEN 'lb' THEN o.value_num * 0.45359237 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
    WHERE o.system = 'http://loinc.org' AND o.code = '29463-7') WHERE rn = 1),
a_gout_coh_inc_06_1_height AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[in_i]' THEN o.value_num * 2.54 WHEN 'cm' THEN o.value_num * 1.0 WHEN 'in' THEN o.value_num * 2.54 WHEN 'm' THEN o.value_num * 100.0 WHEN 'mm' THEN o.value_num * 0.1 ELSE NULL END)) THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN '[in_i]' THEN o.value_num * 2.54 WHEN 'cm' THEN o.value_num * 1.0 WHEN 'in' THEN o.value_num * 2.54 WHEN 'm' THEN o.value_num * 100.0 WHEN 'mm' THEN o.value_num * 0.1 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
    WHERE o.system = 'http://loinc.org' AND o.code = '8302-2') WHERE rn = 1),
a_gout_coh_inc_06_1_v AS (
  SELECT b.pid, b.index_date, weight.conv / pow(height.conv / 100.0, 2) AS val, concat_ws(';', weight.oid || '|' || strftime(weight.effective, '%Y-%m-%d'), height.oid || '|' || strftime(height.effective, '%Y-%m-%d')) AS refs,
         (CASE WHEN weight.oid IS NULL OR weight.value_num IS NULL THEN 'derived_missing_input:weight' WHEN weight.conv IS NULL THEN 'derived_unit:weight' WHEN height.oid IS NULL OR height.value_num IS NULL THEN 'derived_missing_input:height' WHEN height.conv IS NULL THEN 'derived_unit:height' ELSE 'derived_missing_input' END) AS why
  FROM base b
  LEFT JOIN a_gout_coh_inc_06_1_weight weight ON weight.pid = b.pid AND weight.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_06_1_height height ON height.pid = b.pid AND height.index_date = b.index_date),
a_gout_coh_inc_06_1 AS (
  SELECT pid, index_date, val, CASE WHEN val IS NULL THEN why ELSE refs END AS ev
  FROM a_gout_coh_inc_06_1_v),
-- GOUT-COH-INC-06 (inclusion): 一年內最近一次身體質量指數大於或等於 27 kg/m²。
c_gout_coh_inc_06 AS (
  SELECT b.pid, b.index_date, (a_gout_coh_inc_06_1.val >= 27) AS v,
         concat_ws(';', a_gout_coh_inc_06_1.ev) AS ev
  FROM base b
  LEFT JOIN a_gout_coh_inc_06_1 ON a_gout_coh_inc_06_1.pid = b.pid AND a_gout_coh_inc_06_1.index_date = b.index_date),
a_gout_coh_inc_07_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_2_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_07_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_2_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_TYPE_2_DIABETES_MELLITUS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_2_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_gout_coh_inc_07_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_TYPE_2_DIABETES_MELLITUS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TYPE_2_DIABETES_MELLITUS' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
-- GOUT-COH-INC-07 (inclusion): 合併第二型糖尿病診斷。
c_gout_coh_inc_07 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_gout_coh_inc_07_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_gout_coh_inc_07_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_gout_coh_inc_07_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_gout_coh_inc_07_1.ev, a_gout_coh_inc_07_1_off.ev, a_gout_coh_inc_07_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_gout_coh_inc_07_1 ON a_gout_coh_inc_07_1.pid = b.pid AND a_gout_coh_inc_07_1.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_07_1_nd ON a_gout_coh_inc_07_1_nd.pid = b.pid AND a_gout_coh_inc_07_1_nd.index_date = b.index_date
  LEFT JOIN a_gout_coh_inc_07_1_off ON a_gout_coh_inc_07_1_off.pid = b.pid AND a_gout_coh_inc_07_1_off.index_date = b.index_date)
SELECT b.pid, b.index_date,
  c_gout_coh_inc_01.v AS "C_GOUT-COH-INC-01", c_gout_coh_inc_01.ev AS "E_GOUT-COH-INC-01",
  c_gout_coh_inc_02.v AS "C_GOUT-COH-INC-02", c_gout_coh_inc_02.ev AS "E_GOUT-COH-INC-02",
  c_gout_coh_inc_03.v AS "C_GOUT-COH-INC-03", c_gout_coh_inc_03.ev AS "E_GOUT-COH-INC-03",
  c_gout_coh_inc_04.v AS "C_GOUT-COH-INC-04", c_gout_coh_inc_04.ev AS "E_GOUT-COH-INC-04",
  c_gout_coh_inc_05.v AS "C_GOUT-COH-INC-05", c_gout_coh_inc_05.ev AS "E_GOUT-COH-INC-05",
  c_gout_coh_inc_06.v AS "C_GOUT-COH-INC-06", c_gout_coh_inc_06.ev AS "E_GOUT-COH-INC-06",
  c_gout_coh_inc_07.v AS "C_GOUT-COH-INC-07", c_gout_coh_inc_07.ev AS "E_GOUT-COH-INC-07"
FROM base b
LEFT JOIN c_gout_coh_inc_01 ON c_gout_coh_inc_01.pid = b.pid AND c_gout_coh_inc_01.index_date = b.index_date
LEFT JOIN c_gout_coh_inc_02 ON c_gout_coh_inc_02.pid = b.pid AND c_gout_coh_inc_02.index_date = b.index_date
LEFT JOIN c_gout_coh_inc_03 ON c_gout_coh_inc_03.pid = b.pid AND c_gout_coh_inc_03.index_date = b.index_date
LEFT JOIN c_gout_coh_inc_04 ON c_gout_coh_inc_04.pid = b.pid AND c_gout_coh_inc_04.index_date = b.index_date
LEFT JOIN c_gout_coh_inc_05 ON c_gout_coh_inc_05.pid = b.pid AND c_gout_coh_inc_05.index_date = b.index_date
LEFT JOIN c_gout_coh_inc_06 ON c_gout_coh_inc_06.pid = b.pid AND c_gout_coh_inc_06.index_date = b.index_date
LEFT JOIN c_gout_coh_inc_07 ON c_gout_coh_inc_07.pid = b.pid AND c_gout_coh_inc_07.index_date = b.index_date
ORDER BY b.pid, b.index_date
